// ponytail: mirrors the old Taiga project-creation step, adapted to
// Kaneo's workspace -> project -> task hierarchy (no epic/userstory/issue
// resources -- see AGENT.md's "Kaneo" section). One shared 'sdlc' workspace
// holds every generated project, same role the single Taiga instance played.
const auth = { Authorization: `Bearer ${$env.KANEO_TOKEN}` };
const projectName = $node['Webhook Trigger'].json.body.body.project ?? 'hr-portal';
const slug = projectName.toString().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

// ponytail: verify this exact path against the deployed Kaneo version --
// GET /api/workspace (list) is inferred from the confirmed GET /api/project
// naming convention, not confirmed from docs.
const workspaces = await this.helpers.httpRequest({ method: 'GET', url: `${$env.KANEO_URL}/api/workspace`, headers: auth, json: true, ignoreHttpStatusErrors: true });
let workspace = (Array.isArray(workspaces) ? workspaces : workspaces?.workspaces || []).find(w => w.slug === 'sdlc' || w.name === 'sdlc');
if (!workspace) {
  // ponytail: verify this exact path/body against the deployed Kaneo version.
  workspace = await this.helpers.httpRequest({ method: 'POST', url: `${$env.KANEO_URL}/api/workspace`, headers: auth, json: true, body: { name: 'sdlc', slug: 'sdlc' } });
}
const workspaceId = workspace.id;

// GET /api/project -- confirmed endpoint, lists projects in a workspace.
const projects = await this.helpers.httpRequest({ method: 'GET', url: `${$env.KANEO_URL}/api/project`, headers: auth, json: true, qs: { workspaceId }, ignoreHttpStatusErrors: true });
const existing = (Array.isArray(projects) ? projects : projects?.projects || []).find(p => p.slug === slug || p.name === projectName);
if (existing) {
  return [{ json: { kaneo_workspace_id: workspaceId, kaneo_project_id: existing.id, kaneo_project_slug: existing.slug, kaneo_project_created: false } }];
}

// ponytail: verify this exact path/body against the deployed Kaneo version
// -- POST /api/project is inferred from the confirmed GET /api/project
// naming convention, not confirmed from docs.
const created = await this.helpers.httpRequest({ method: 'POST', url: `${$env.KANEO_URL}/api/project`, headers: auth, json: true, body: { name: projectName, slug, workspaceId, description: `${projectName} \u2014 created by /kickoff` } });
return [{ json: { kaneo_workspace_id: workspaceId, kaneo_project_id: created.id, kaneo_project_slug: created.slug, kaneo_project_created: true } }];

// ponytail: one dedicated Kaneo user per SDLC role (created once by
// helm/ansible/playbooks/role-accounts.yml, email sdlc-<role>@homelab.local)
// so tickets can be assigned to the role that did the work instead of the
// single shared admin identity. Kaneo membership is per-project -- same
// per-project-at-kickoff-time call the old Taiga membership step made.
const auth = { Authorization: `Bearer ${$env.KANEO_TOKEN}` };
const projectId = $json.kaneo_project_id;
const sdlcRoles = ['backend-developer','data-engineer','devops-engineer','frontend-developer','product-owner','project-manager','qa-engineer','release-manager','security-engineer','solution-architect','tech-lead','uiux-designer'];

// ponytail: verify this exact path against the deployed Kaneo version -- a
// plain user-listing endpoint isn't confirmed from docs, inferred from the
// same /api/<resource> convention as the confirmed project/task ones.
const allUsers = await this.helpers.httpRequest({ method: 'GET', url: `${$env.KANEO_URL}/api/user`, headers: auth, json: true });
const userList = Array.isArray(allUsers) ? allUsers : (allUsers?.users || []);

const added = [];
const skipped = [];
for (const roleName of sdlcRoles) {
  const email = `sdlc-${roleName}@homelab.local`;
  const user = userList.find(u => u.email === email);
  if (!user) { skipped.push(roleName); continue; }
  try {
    // ponytail: verify this exact path against the deployed Kaneo version
    // -- POST /api/project/<id>/members inferred from the confirmed
    // /api/project naming convention.
    await this.helpers.httpRequest({ method: 'POST', url: `${$env.KANEO_URL}/api/project/${projectId}/members`, headers: auth, json: true, body: { userId: user.id, role: 'member' } });
    added.push(roleName);
  } catch (e) {
    // already a member -- tolerate like the old Taiga 400-on-duplicate path
    added.push(roleName);
  }
}
if (skipped.length) {
  console.log(`Role accounts not found in Kaneo (run role-accounts.yml first): ${skipped.join(', ')}`);
}
return [{ json: { ...$json, role_members_added: added, role_members_skipped: skipped } }];

// ponytail: wires Kaneo's own native GitLab integration (real
// bidirectional sync, merged upstream 2026-09-26 -- see AGENT.md's "Kaneo"
// section) onto the project just ensured above, so Kaneo's board stays in
// sync with this project's GitLab activity without a separate webhook
// playbook (unlike Taiga's old one-way compliance webhook).
const auth = { Authorization: `Bearer ${$env.KANEO_TOKEN}` };
const projectId = $json.kaneo_project_id;
const group = $node['Webhook Trigger'].json.body.body.group ?? 'sdlc';
const project = $node['Webhook Trigger'].json.body.body.project ?? 'hr-portal';
const gitlabProjectPath = `${group}/${project}`;

// ponytail: verify this exact Kaneo integration-config endpoint path
// against the deployed version -- inferred from the confirmed
// /api/project/<id>/... nesting convention, not confirmed from docs. Best
// effort / fire-and-forget: a failure here shouldn't block the rest of
// kickoff, Kaneo tickets still work fine without GitLab sync wired up.
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${$env.KANEO_URL}/api/project/${projectId}/integrations/gitlab`,
    headers: auth,
    json: true,
    body: {
      gitlabUrl: 'http://gitlab-webservice-default.gitlab.svc.cluster.local:8181',
      gitlabToken: $env.GITLAB_TOKEN,
      projectPath: gitlabProjectPath,
    },
    ignoreHttpStatusErrors: true,
  });
} catch (e) {
  console.log(`Kaneo GitLab integration config failed (non-fatal): ${e.message}`);
}

return [{ json: { ...$json, kaneo_gitlab_integration_configured: true } }];
